/* Storage behind the API. PgStore for PostgreSQL (DATABASE_URL), MemoryStore for local development. Generated by Chakram. */
import { randomUUID } from 'node:crypto';
import postgres from 'postgres';
import { entities, type EntityName } from './schema.js';

export type Row = Record<string, unknown> & { id: string; orgId: string; createdAt: string; updatedAt: string };
export type ListQuery = { sort?: string; dir?: 'asc' | 'desc'; limit?: number; offset?: number; filter?: Record<string, string> };
export type ListResult = { rows: Row[]; total: number };

export interface Store {
  list(entity: EntityName, orgId: string, query: ListQuery): Promise<ListResult>;
  get(entity: EntityName, orgId: string, id: string): Promise<Row | null>;
  create(entity: EntityName, orgId: string, data: Record<string, unknown>): Promise<Row>;
  update(entity: EntityName, orgId: string, id: string, data: Record<string, unknown>): Promise<Row | null>;
  remove(entity: EntityName, orgId: string, id: string): Promise<boolean>;
  count(entity: EntityName, orgId: string): Promise<number>;
  // users and sessions
  findUserByEmail(email: string): Promise<User | null>;
  findUserById(id: string): Promise<User | null>;
  createUser(user: Omit<User, 'createdAt'>): Promise<User>;
  createSession(token: string, userId: string, expiresAt: string): Promise<void>;
  findSession(token: string): Promise<{ userId: string; expiresAt: string } | null>;
  deleteSession(token: string): Promise<void>;
  ensureOrg(id: string, name: string): Promise<void>;
}

export type User = { id: string; orgId: string; email: string; name: string; passwordHash: string; role: 'owner' | 'member' | 'viewer'; createdAt: string };

const toSnake = (s: string) => s.replace(/(?<=[a-z0-9])(?=[A-Z])/g, '_').toLowerCase();
const toCamel = (s: string) => s.replace(/_([a-z])/g, (_m, c: string) => c.toUpperCase());

function nowIso(): string {
  return new Date().toISOString();
}

function applyQuery(rows: Row[], query: ListQuery): ListResult {
  let out = rows;
  for (const [field, value] of Object.entries(query.filter ?? {})) {
    out = out.filter((r) => String(r[field]) === value);
  }
  if (query.sort) {
    const key = query.sort;
    const dir = query.dir === 'asc' ? 1 : -1;
    out = [...out].sort((a, b) => (String(a[key] ?? '') > String(b[key] ?? '') ? dir : String(a[key] ?? '') < String(b[key] ?? '') ? -dir : 0));
  }
  const total = out.length;
  const offset = Math.max(0, query.offset ?? 0);
  const limit = Math.min(500, Math.max(1, query.limit ?? 100));
  return { rows: out.slice(offset, offset + limit), total };
}

/** In-memory store for development and tests. Nothing survives a restart. */
export class MemoryStore implements Store {
  private rows = new Map<string, Row[]>();
  private users: User[] = [];
  private sessions = new Map<string, { userId: string; expiresAt: string }>();
  private orgs = new Map<string, string>();

  private bucket(entity: EntityName): Row[] {
    let list = this.rows.get(entity);
    if (!list) {
      list = [];
      this.rows.set(entity, list);
    }
    return list;
  }

  async list(entity: EntityName, orgId: string, query: ListQuery): Promise<ListResult> {
    return applyQuery(this.bucket(entity).filter((r) => r.orgId === orgId), query);
  }
  async get(entity: EntityName, orgId: string, id: string): Promise<Row | null> {
    return this.bucket(entity).find((r) => r.orgId === orgId && r.id === id) ?? null;
  }
  async create(entity: EntityName, orgId: string, data: Record<string, unknown>): Promise<Row> {
    const stamp = nowIso();
    const row: Row = { ...data, id: typeof data.id === 'string' && data.id ? data.id : randomUUID(), orgId, createdAt: stamp, updatedAt: stamp };
    this.bucket(entity).push(row);
    return row;
  }
  async update(entity: EntityName, orgId: string, id: string, data: Record<string, unknown>): Promise<Row | null> {
    const row = await this.get(entity, orgId, id);
    if (!row) return null;
    Object.assign(row, data, { id, orgId, updatedAt: nowIso() });
    return row;
  }
  async remove(entity: EntityName, orgId: string, id: string): Promise<boolean> {
    const list = this.bucket(entity);
    const index = list.findIndex((r) => r.orgId === orgId && r.id === id);
    if (index === -1) return false;
    list.splice(index, 1);
    return true;
  }
  async count(entity: EntityName, orgId: string): Promise<number> {
    return this.bucket(entity).filter((r) => r.orgId === orgId).length;
  }
  async findUserByEmail(email: string): Promise<User | null> {
    return this.users.find((u) => u.email === email.toLowerCase()) ?? null;
  }
  async findUserById(id: string): Promise<User | null> {
    return this.users.find((u) => u.id === id) ?? null;
  }
  async createUser(user: Omit<User, 'createdAt'>): Promise<User> {
    const full: User = { ...user, email: user.email.toLowerCase(), createdAt: nowIso() };
    this.users.push(full);
    return full;
  }
  async createSession(token: string, userId: string, expiresAt: string): Promise<void> {
    this.sessions.set(token, { userId, expiresAt });
  }
  async findSession(token: string) {
    return this.sessions.get(token) ?? null;
  }
  async deleteSession(token: string): Promise<void> {
    this.sessions.delete(token);
  }
  async ensureOrg(id: string, name: string): Promise<void> {
    this.orgs.set(id, name);
  }
}

/** PostgreSQL store. Tables come from api/migrations; every query is scoped by org_id. */
export class PgStore implements Store {
  private sql: ReturnType<typeof postgres>;

  constructor(databaseUrl: string) {
    this.sql = postgres(databaseUrl, { max: 10, transform: { undefined: null } });
  }

  private table(entity: EntityName): string {
    return entities[entity].table;
  }

  private fromDb(row: Record<string, unknown>): Row {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(row)) out[toCamel(k)] = v instanceof Date ? v.toISOString() : v;
    return out as Row;
  }

  private toDb(data: Record<string, unknown>): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(data)) out[toSnake(k)] = v;
    return out;
  }

  async list(entity: EntityName, orgId: string, query: ListQuery): Promise<ListResult> {
    const table = this.table(entity);
    const rows = await this.sql`select * from ${this.sql(table)} where org_id = ${orgId}`;
    return applyQuery(rows.map((r) => this.fromDb(r)), query);
  }
  async get(entity: EntityName, orgId: string, id: string): Promise<Row | null> {
    const rows = await this.sql`select * from ${this.sql(this.table(entity))} where org_id = ${orgId} and id = ${id} limit 1`;
    return rows.length ? this.fromDb(rows[0]) : null;
  }
  async create(entity: EntityName, orgId: string, data: Record<string, unknown>): Promise<Row> {
    const stamp = new Date();
    const id = typeof data.id === 'string' && data.id ? data.id : randomUUID();
    const record = this.toDb({ ...data, id, orgId, createdAt: stamp, updatedAt: stamp });
    const rows = await this.sql`insert into ${this.sql(this.table(entity))} ${this.sql(record)} returning *`;
    return this.fromDb(rows[0]);
  }
  async update(entity: EntityName, orgId: string, id: string, data: Record<string, unknown>): Promise<Row | null> {
    const record = this.toDb({ ...data, updatedAt: new Date() });
    delete record.id;
    delete record.org_id;
    const rows = await this.sql`update ${this.sql(this.table(entity))} set ${this.sql(record)} where org_id = ${orgId} and id = ${id} returning *`;
    return rows.length ? this.fromDb(rows[0]) : null;
  }
  async remove(entity: EntityName, orgId: string, id: string): Promise<boolean> {
    const rows = await this.sql`delete from ${this.sql(this.table(entity))} where org_id = ${orgId} and id = ${id} returning id`;
    return rows.length > 0;
  }
  async count(entity: EntityName, orgId: string): Promise<number> {
    const rows = await this.sql`select count(*)::int as n from ${this.sql(this.table(entity))} where org_id = ${orgId}`;
    return Number(rows[0]?.n ?? 0);
  }
  async findUserByEmail(email: string): Promise<User | null> {
    const rows = await this.sql`select * from users where email = ${email.toLowerCase()} limit 1`;
    return rows.length ? (this.fromDb(rows[0]) as unknown as User) : null;
  }
  async findUserById(id: string): Promise<User | null> {
    const rows = await this.sql`select * from users where id = ${id} limit 1`;
    return rows.length ? (this.fromDb(rows[0]) as unknown as User) : null;
  }
  async createUser(user: Omit<User, 'createdAt'>): Promise<User> {
    const rows = await this.sql`insert into users ${this.sql(this.toDb({ ...user, email: user.email.toLowerCase() }))} returning *`;
    return this.fromDb(rows[0]) as unknown as User;
  }
  async createSession(token: string, userId: string, expiresAt: string): Promise<void> {
    await this.sql`insert into sessions (token, user_id, expires_at) values (${token}, ${userId}, ${expiresAt})`;
  }
  async findSession(token: string) {
    const rows = await this.sql`select user_id, expires_at from sessions where token = ${token} limit 1`;
    if (!rows.length) return null;
    const row = rows[0];
    const expires = row.expires_at instanceof Date ? row.expires_at.toISOString() : String(row.expires_at);
    return { userId: String(row.user_id), expiresAt: expires };
  }
  async deleteSession(token: string): Promise<void> {
    await this.sql`delete from sessions where token = ${token}`;
  }
  async ensureOrg(id: string, name: string): Promise<void> {
    await this.sql`insert into orgs (id, name) values (${id}, ${name}) on conflict (id) do nothing`;
  }
}

export function createStore(): Store {
  const url = process.env.DATABASE_URL;
  if (url) return new PgStore(url);
  console.warn('[api] DATABASE_URL is not set: using the in-memory store (data is lost on restart).');
  return new MemoryStore();
}
